float value = 9.8f;
const int read_only = 50;
int* ptr_i = &read_only;

// Static_cast: Conversions and safe hierarchies
int i_c = (int)value;
int i_cpp = static_cast<int>(value);

// Const_cast: Explicitly removing const/volatile
int* p_c = (int*)&read_only;
int* p_cpp = const_cast<int*>(&read_only);

// Reinterpret_cast: Low-level bit remapping
char* c_c = (char*)ptr_i;
char* c_cpp = reinterpret_cast<char*>(ptr_i);

// Dynamic_cast: Runtime checking (Polymorphic hierarchies)
struct Base { virtual ~Base() = default; };
struct Derived : Base {};
Base* b = new Derived;
// Derived* d_c = (Derived*)b; // Unsafe
Derived* d_cpp = dynamic_cast<Derived*>(b); // Safe, returns nullptr on fail
